def digest(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def main():
 parser=argparse.ArgumentParser(description=__doc__)
 parser.add_argument('--java-home',type=pathlib.Path,required=True)
 parser.add_argument('--dependencies-json',type=pathlib.Path,required=True)
 parser.add_argument('--output',type=pathlib.Path,required=True)
 args=parser.parse_args()
 global JDK, DEPS
 JDK=args.java_home.resolve()/'bin';DEPS=args.dependencies_json.resolve()
 out=args.output.absolute();out.mkdir(mode=0o700);prod=out/'production';fake=out/'fixture';src=out/'stubs';empty=out/'empty';
 for q in (prod,fake,src,empty):q.mkdir()
 paths=[]
 for n,v in STUBS.items():
  f=src/n;f.parent.mkdir(parents=True,exist_ok=True);f.write_text(v);paths.append(f)
 deps=[pathlib.Path(x) for x in json.loads(DEPS.read_text())];
 if not deps or any(not p.is_absolute() or not p.exists() for p in deps):raise ValueError('classpath entries must be existing absolute paths')
 cp=os.pathsep.join(map(str,deps));
 names=['ControlAuthorityArbiter','FormationFlightManager','AirspaceSafetyProbe','MobPilotGate','ControlOutcome','ControlProposal','FlightControlOutput','FlightPhase','AutopilotSession','FlightProfile']
 actual=[ROOT/'com/wwdebug/autopilot'/(n+'.java') for n in names]; inputs=actual+paths+[JDK/'java',JDK/'javac',DEPS,pathlib.Path(__file__)];
 def inventory(entries):
  out={}
  for entry in entries:
   files=sorted(f for f in entry.rglob('*') if f.is_file()) if entry.is_dir() else [entry]
   for item in files:out[str(item)]=digest(item)
  return out
 before={str(x):digest(x) for x in inputs}; deps_before=inventory(deps); shutil.copyfile(__file__,out/'runner-snapshot.py'); report={'base':'2585f44fa02b84ed7f593bf9a65798a2b4f056ea','scope':'Actual session/profile/arbiter/formation/geometry; manager/snapshot/terrain-active/aircraft/log are stand-ins; no real motion or server. Terrain case observes only fake active flag branch, not actual terrain planning or avoidance input. Player is passed through fake manager cleanup.','runner_snapshot_sha256':digest(out/'runner-snapshot.py'),'inputs_before':before,'classpath_before':deps_before,'runs':{}}
 def run(name,args):
  r=subprocess.run(args,cwd=out,capture_output=True,text=True,timeout=30);(out/(name+'.stdout')).write_text(r.stdout);(out/(name+'.stderr')).write_text(r.stderr);report['runs'][name]={'argv':args,'exit':r.returncode};print(name,r.returncode,flush=True);return r.returncode
 rc=run('compile-production',[str(JDK/'javac'),'-proc:none','--release','17','-cp',cp,'-sourcepath',str(empty),'-d',str(prod),*map(str,actual)])
 if not rc:rc=run('compile-fixture',[str(JDK/'javac'),'-proc:none','--release','17','-cp',str(prod)+os.pathsep+cp,'-sourcepath',str(empty),'-d',str(fake),*map(str,paths)])
 if not rc:
  for case in ('grouped','ungrouped','terrain','collision','player','timeout'):
   run(case,[str(JDK/'java'),'-Xmx128m','-Xverify:all','-Xlog:class+load=info:file='+str(out/(case+'.classes.log')),'-cp',str(fake)+os.pathsep+str(prod)+os.pathsep+cp,'com.wwdebug.autopilot.Probe',case])
 report['inputs_after']={str(x):digest(x) for x in inputs}; report['inputs_unchanged']=report['inputs_before']==report['inputs_after'];report['classpath_after']=inventory(deps);report['classpath_unchanged']=deps_before==report['classpath_after'];report['compiled_production']=inventory([prod]);report['compiled_fixture']=inventory([fake]);(out/'report.json').write_text(json.dumps(report,indent=2)+'\n');return 0 if report['inputs_unchanged'] and report['classpath_unchanged'] and all(x['exit']==0 for x in report['runs'].values()) and len(report['runs'])==8 else 1
if __name__=='__main__':sys.exit(main())
